import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { LEVELS, create, replay, solve } from '../src';

const lines: string[] = [
  '# Level solvability report',
  '',
  'Generated by `npm run verify:levels` (breadth-first search over the real engine).',
  '"Dead states" are reachable world states from which no win exists even with unlimited actions; RESET is the only way out of them.',
  '',
  '| Level | Budget | Optimal | Slack | Distinct optimal solutions | Reachable states | Dead states | Replay-verified | Verdict |',
  '|---|---|---|---|---|---|---|---|---|',
];
let failed = false;
const detail: string[] = [];

for (const level of LEVELS) {
  create(level, 'verify'); // throws on structurally invalid challenges
  const r = solve(level);
  const outcome = r.optimalSolution ? replay(level, r.optimalSolution) : null;
  const verified = !!outcome && outcome.won && outcome.actionsUsed === r.optimalLength && !outcome.extraActions;
  const ok = r.solvable && r.withinBudget && verified;
  if (!ok) failed = true;
  lines.push(
    `| ${level.id} | ${level.budget} | ${r.optimalLength ?? '—'} | ${r.optimalLength === null ? '—' : level.budget - r.optimalLength} | ${r.optimalSolutionCount} | ${r.reachableStates} | ${r.deadStates} | ${verified ? 'yes' : 'NO'} | ${ok ? 'PASS' : 'FAIL'} |`,
  );
  detail.push(`- **${level.id}**: \`${(r.optimalSolution ?? []).map((a) => (a.type === 'MOVE' ? a.direction[0] : a.type === 'INTERACT' ? `[${a.targetId}]` : 'RESET')).join(' ')}\``);
}
lines.push('', '## One optimal solution per level (U/D/L/R = move, [id] = interact)', '', ...detail, '');
const out = fileURLToPath(new URL('../../../docs/verification/solvability-report.md', import.meta.url));
writeFileSync(out, lines.join('\n'));
console.log(lines.join('\n'));
if (failed) {
  console.error('\nSOLVABILITY VERIFICATION FAILED');
  process.exit(1);
}
